"""The survey terrain: generated by Isaac Lab's TerrainGenerator on the CPU (needs env_isaaclab, no Kit)."""

from __future__ import annotations

import numpy as np

from _runner import main_for, require


def _terrain():
    require("isaaclab")
    require("trimesh")
    import drone_lab.terrain as terrain

    return terrain


def test_terrain_is_deterministic_and_independent_of_global_rng():
    t = _terrain()
    np.random.seed(1)
    v1, f1 = t.generate_terrain_mesh()
    np.random.seed(2)
    v2, f2 = t.generate_terrain_mesh()
    assert np.array_equal(v1, v2) and np.array_equal(f1, f2)
    state = np.random.get_state()
    t.generate_terrain_mesh()
    assert np.array_equal(state[1], np.random.get_state()[1])  # global RNG left untouched


def test_terrain_size_heights_and_no_gaps():
    t = _terrain()
    from drone_lab.mapping import MeshHeightQuery

    v, f = t.generate_terrain_mesh()
    area = t.terrain_area(t.SURVEY_TERRAIN_CFG)
    assert (area.width, area.height) == (40.0, 40.0)
    border = t.SURVEY_TERRAIN_CFG.border_width
    assert np.allclose(v[:, :2].min(axis=0), [-20 - border] * 2) and np.allclose(v[:, :2].max(axis=0), [20 + border] * 2)
    inside = area.contains(v[:, :2])
    z = v[inside, 2]
    assert 2.0 < z.max() < 4.5 and -3.0 < z.min() < 0.0, (z.min(), z.max())
    rng = np.random.default_rng(0)
    q = rng.uniform(-20 - border + 0.01, 20 + border - 0.01, (100_000, 2))
    h = MeshHeightQuery(v, f)(q)
    assert not np.isnan(h).any(), f"{np.isnan(h).mean():.4%} of the terrain is not covered from above"


def test_tile_seed_and_blocks_terrain():
    t = _terrain()
    cfg = t.SteppedBlocksTerrainCfg(height_range=(1.0, 2.0), size=(10.0, 10.0))
    cfg.seed = 5
    assert t.tile_seed(cfg, 0.5) == t.tile_seed(cfg, 0.5) != t.tile_seed(cfg, 0.6)
    meshes, origin = t.stepped_blocks_terrain(1.0, cfg)
    zmax = max(m.vertices[:, 2].max() for m in meshes)
    assert 0.5 <= zmax <= 2.0 + 1e-6 and origin.shape == (3,)


if __name__ == "__main__":
    main_for(globals(), "test_terrain")
